import os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    import re
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

from collections import deque
def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    # enclosed zeros via flood fill from border over non-5
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]!=5: q.append((i,j)); seen[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]!=5: q.append((i,j)); seen[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]!=5:
                seen[ni][nj]=True; q.append((ni,nj))
    ints=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and not seen[i][j]:
                out[i][j]=2; ints.append((i,j))
    # group shapes by connected 5 components to find tops
    lab=[[0]*w for _ in range(h)]; c=0
    for i in range(h):
        for j in range(w):
            if g[i][j]==5 and not lab[i][j]:
                c+=1; q=deque([(i,j)]); lab[i][j]=c; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+di,b+dj
                        if 0<=na<h and 0<=nb<w and g[na][nb]==5 and not lab[na][nb]:
                            lab[na][nb]=c; q.append((na,nb))
                top=min(a for a,b in cells); right=max(b for a,b in cells)
                r=top-1
                if r>=0:
                    for j2 in range(0,right):
                        out[r][j2]=2
    return out
